
(function(root){'use strict';const N=root.NeonCombat,D=N.Dialogue143;
D.enqueue=function(g,text,{speaker='',duration=3,kind='ambient',scene=null}={}){g.dialogue143??=[];const previous=g.dialogue143.at(-1),at=Math.max(g.time,previous?previous.at+previous.duration:g.time);g.dialogue143.push({text:String(text),speaker,kind,scene,at,duration:Math.max(.2,duration)});};D.current=function(g){g.dialogue143=(g.dialogue143||[]).filter(x=>g.time<x.at+x.duration);return g.dialogue143.find(x=>g.time>=x.at)||null;};D.scene=function(g,id,lines,kind='strategy'){for(const line of lines)D.enqueue(g,line.text,{speaker:line.speaker||'',duration:line.duration||3,kind,scene:id});};D.cancel=function(g){g.dialogue143=[];};
function compare(reports){const out={};for(const r of reports){if(!r||!r.hero||!r.counts||!Array.isArray(r.events))continue;const row=out[r.hero]??={runs:0,seconds:0,damageTaken:0,knockdowns:0,successfulAttacks:0,missedAttacks:0,completed:0,defeated:0};row.runs++;row.seconds+=r.duration||0;row.damageTaken+=r.counts.damageTaken||0;row.knockdowns+=r.counts.playerKnockdowns||0;row.successfulAttacks+=r.counts.successfulPlayerAttacks||0;row.missedAttacks+=r.counts.missedPlayerAttacks||0;row.completed+=r.events.some(e=>e.type==='victory')?1:0;row.defeated+=r.events.some(e=>e.type==='defeat')?1:0;}for(const row of Object.values(out)){row.damagePerRun=row.damageTaken/row.runs;row.hitPercent=row.successfulAttacks+row.missedAttacks?100*row.successfulAttacks/(row.successfulAttacks+row.missedAttacks):null;row.completionPercent=100*row.completed/row.runs;}return{heroes:out,warning:'Compare matched encounters, duration and player strategy. Unfinished runs are not survival failures. No tuning is applied.'};}
N.Review144={compare};
})(typeof window!=='undefined'?window:globalThis);
